window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-541ddc08f3983a8e"]={"versions": [{"id": "FIG-541ddc08f3983a8e", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenzdiagramm zur Veranschaulichung des Datenflusses für das Broadcast Announce Message (BAM) Transportprotokoll im Kontext des AUTOSAR SAE J1939 Transport Layers (<code>J1939Tp</code>). Das Diagramm illustriert den unbestätigten, unidirektionalen Transfer segmentierter Botschaften von einem sendenden Netzknoten an ein Broadcast-Ziel über zwei vertikale Lebenslinien hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei unbeschriftete vertikale Lebenslinien repräsentieren die beteiligten Kommunikationspartner (Sender auf der linken Seite, Empfänger bzw. Broadcast-Ziel auf der rechten Seite). Als Protokollnachrichten bzw. PDUs werden ein Verbindungsverwaltungs-Frame <code>TP.CM_BAM</code> mit dem Parameter <code>total Byte Length= 16</code> sowie drei aufeinanderfolgende Datentransfer-Frames <code>TP.DT</code> übertragen. Als Zeitparameter und Überwachungsintervalle sind <code>50ms .. Tr</code> sowie <code>T1</code> definiert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf stellt eine BAM-Übertragung einer 16-Byte-Gesamtnachricht dar:</p>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Übertragung mit einem <code>TP.CM_BAM</code>-Frame in Richtung Empfänger (<code>total Byte Length= 16</code>).\n</li><li>Der Mindestabstand zwischen dem Verbindungsaufbau-Frame und dem ersten Datenpaket sowie zwischen nachfolgenden Datenpaketen wird senderseitig durch das Intervall <code>50ms .. Tr</code> bestimmt.\n</li><li>Der Sender übermittelt sukzessive drei <code>TP.DT</code>-Frames, um die 16 Nutzdatenbytes segmentiert zu übertragen (jeweils bis zu 7 Datenbytes pro Frame).\n</li><li>Empfängerseitig markiert <code>T1</code> den Timeout-Überwachungszeitraum zwischen dem Empfang von <code>TP.CM_BAM</code> und dem ersten Datenpaket <code>TP.DT</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt informativen Charakter zur Verdeutlichung der J1939 BAM-Timing-Vorgaben nach SAE J1939-21:</p>\n<ul class=\"fig-list\"><li>Senderseitig ist der minimale Sendeabstand von 50 ms zwischen Paketen (<code>50ms .. Tr</code>) zwingend einzuhalten.\n</li><li>Empfängerseitig führt der Ablauf des Timers <code>T1</code> ohne Empfang des Folgepakets zum Verbindungsabbruch bzw. Verwerfen der unvollständigen Nachricht.\n</li><li>Da es sich um BAM handelt, erfolgen keine Bestätigungen (<code>TP.CM_CTS</code> oder <code>TP.EndofMsgACK</code>) durch den Empfänger.\n</li></ul>"}, {"id": "FIG-d7c661542d94d698", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenzdiagramm zur Veranschaulichung des Datenflusses für das Broadcast Announce Message (BAM) Transportprotokoll im Kontext des AUTOSAR SAE J1939 Transport Layers (<code>J1939Tp</code>). Das Diagramm illustriert den unbestätigten, unidirektionalen Transfer segmentierter Botschaften von einem sendenden Netzknoten an ein Broadcast-Ziel über zwei vertikale Lebenslinien hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei explizit benannte Lebenslinien repräsentieren die Kommunikationspartner:</p>\n<ul class=\"fig-list\"><li><code>Sender</code> (linke vertikale Lebenslinie)\n</li><li><code>Receiver</code> (rechte vertikale Lebenslinie)\n</li></ul>\n<p class=\"fig-p\">Die Schnittstellen und Nachrichten umfassen:</p>\n<ul class=\"fig-list\"><li><code>TP.CM_BAM</code> mit Parameter <code>total Byte Length= 16</code>\n</li><li>Drei aufeinanderfolgende <code>TP.DT</code>-Nachrichten\n</li><li>Zeitparameter <code>50ms .. Tr</code> auf Senderseite\n</li><li>Timeout-Intervall <code>T1</code> auf Empfängerseite\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf stellt eine BAM-Übertragung einer 16-Byte-Gesamtnachricht dar:</p>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Übertragung mit einem <code>TP.CM_BAM</code>-Frame in Richtung Empfänger (<code>total Byte Length= 16</code>).\n</li><li>Der Mindestabstand zwischen dem Verbindungsaufbau-Frame und dem ersten Datenpaket sowie zwischen nachfolgenden Datenpaketen wird senderseitig durch das Intervall <code>50ms .. Tr</code> bestimmt.\n</li><li>Der Sender übermittelt sukzessive drei <code>TP.DT</code>-Frames, um die 16 Nutzdatenbytes segmentiert zu übertragen (jeweils bis zu 7 Datenbytes pro Frame).\n</li><li>Empfängerseitig markiert <code>T1</code> den Timeout-Überwachungszeitraum zwischen dem Empfang von <code>TP.CM_BAM</code> und dem ersten Datenpaket <code>TP.DT</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt informativen Charakter zur Verdeutlichung der J1939 BAM-Timing-Vorgaben nach SAE J1939-21:</p>\n<ul class=\"fig-list\"><li>Senderseitig ist der minimale Sendeabstand von 50 ms zwischen Paketen (<code>50ms .. Tr</code>) zwingend einzuhalten.\n</li><li>Empfängerseitig führt der Ablauf des Timers <code>T1</code> ohne Empfang des Folgepakets zum Verbindungsabbruch bzw. Verwerfen der unvollständigen Nachricht.\n</li><li>Da es sich um BAM handelt, erfolgen keine Bestätigungen (<code>TP.CM_CTS</code> oder <code>TP.EndofMsgACK</code>) durch den Empfänger.\n</li></ul>"}, {"id": "FIG-32ff0abffaf22da0", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenzdiagramm zur Veranschaulichung des Datenflusses für das Broadcast Announce Message (BAM) Transportprotokoll im Kontext des AUTOSAR SAE J1939 Transport Layers (<code>J1939Tp</code>). Das Diagramm illustriert den unbestätigten, unidirektionalen Transfer segmentierter Botschaften von einem sendenden Netzknoten an ein Broadcast-Ziel über zwei vertikale Lebenslinien hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei unbeschriftete vertikale Lebenslinien repräsentieren die beteiligten Kommunikationspartner (Sender auf der linken Seite, Empfänger bzw. Broadcast-Ziel auf der rechten Seite). Als Protokollnachrichten bzw. PDUs werden ein Verbindungsverwaltungs-Frame <code>TP.CM_BAM</code> mit dem Parameter <code>total Byte Length= 16</code> sowie drei aufeinanderfolgende Datentransfer-Frames <code>TP.DT</code> übertragen. Als Zeitparameter und Überwachungsintervalle sind <code>50ms .. Tr</code> sowie <code>T1</code> definiert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf stellt eine BAM-Übertragung einer 16-Byte-Gesamtnachricht dar:</p>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Übertragung mit einem <code>TP.CM_BAM</code>-Frame in Richtung Empfänger (<code>total Byte Length= 16</code>).\n</li><li>Der Mindestabstand zwischen dem Verbindungsaufbau-Frame und dem ersten Datenpaket sowie zwischen nachfolgenden Datenpaketen wird senderseitig durch das Intervall <code>50ms .. Tr</code> bestimmt.\n</li><li>Der Sender übermittelt sukzessive drei <code>TP.DT</code>-Frames, um die 16 Nutzdatenbytes segmentiert zu übertragen (jeweils bis zu 7 Datenbytes pro Frame).\n</li><li>Empfängerseitig markiert <code>T1</code> den Timeout-Überwachungszeitraum zwischen dem Empfang von <code>TP.CM_BAM</code> und dem ersten Datenpaket <code>TP.DT</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt informativen Charakter zur Verdeutlichung der J1939 BAM-Timing-Vorgaben nach SAE J1939-21:</p>\n<ul class=\"fig-list\"><li>Senderseitig ist der minimale Sendeabstand von 50 ms zwischen Paketen (<code>50ms .. Tr</code>) zwingend einzuhalten.\n</li><li>Empfängerseitig führt der Ablauf des Timers <code>T1</code> ohne Empfang des Folgepakets zum Verbindungsabbruch bzw. Verwerfen der unvollständigen Nachricht.\n</li><li>Da es sich um BAM handelt, erfolgen keine Bestätigungen (<code>TP.CM_CTS</code> oder <code>TP.EndofMsgACK</code>) durch den Empfänger.\n</li></ul>"}, {"id": "FIG-e2758362d57a8be5", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenzdiagramm zur Veranschaulichung des Datenflusses für das Broadcast Announce Message (BAM) Transportprotokoll im Kontext des AUTOSAR SAE J1939 Transport Layers (<code>J1939Tp</code>). Das Diagramm illustriert den unbestätigten, unidirektionalen Transfer segmentierter Botschaften von einem sendenden Netzknoten an ein Broadcast-Ziel über zwei vertikale Lebenslinien hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei unbeschriftete vertikale Lebenslinien repräsentieren die beteiligten Kommunikationspartner (Sender auf der linken Seite, Empfänger bzw. Broadcast-Ziel auf der rechten Seite). Als Protokollnachrichten bzw. PDUs werden ein Verbindungsverwaltungs-Frame <code>TP.CM_BAM</code> mit dem Parameter <code>total Byte Length= 16</code> sowie drei aufeinanderfolgende Datentransfer-Frames <code>TP.DT</code> übertragen. Als Zeitparameter und Überwachungsintervalle sind <code>50ms .. Tr</code> sowie <code>T1</code> definiert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf stellt eine BAM-Übertragung einer 16-Byte-Gesamtnachricht dar:</p>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Übertragung mit einem <code>TP.CM_BAM</code>-Frame in Richtung Empfänger (<code>total Byte Length= 16</code>).\n</li><li>Der Mindestabstand zwischen dem Verbindungsaufbau-Frame und dem ersten Datenpaket sowie zwischen nachfolgenden Datenpaketen wird senderseitig durch das Intervall <code>50ms .. Tr</code> bestimmt.\n</li><li>Der Sender übermittelt sukzessive drei <code>TP.DT</code>-Frames, um die 16 Nutzdatenbytes segmentiert zu übertragen (jeweils bis zu 7 Datenbytes pro Frame).\n</li><li>Empfängerseitig markiert <code>T1</code> den Timeout-Überwachungszeitraum zwischen dem Empfang von <code>TP.CM_BAM</code> und dem ersten Datenpaket <code>TP.DT</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt informativen Charakter zur Verdeutlichung der J1939 BAM-Timing-Vorgaben nach SAE J1939-21:</p>\n<ul class=\"fig-list\"><li>Senderseitig ist der minimale Sendeabstand von 50 ms zwischen Paketen (<code>50ms .. Tr</code>) zwingend einzuhalten.\n</li><li>Empfängerseitig führt der Ablauf des Timers <code>T1</code> ohne Empfang des Folgepakets zum Verbindungsabbruch bzw. Verwerfen der unvollständigen Nachricht.\n</li><li>Da es sich um BAM handelt, erfolgen keine Bestätigungen (<code>TP.CM_CTS</code> oder <code>TP.EndofMsgACK</code>) durch den Empfänger.\n</li></ul>"}], "trans": [{"from": "FIG-541ddc08f3983a8e", "to": "FIG-d7c661542d94d698", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Rollenbezeichner: Oberhalb der linken Lebenslinie ist die Beschriftung „Sender“ und oberhalb der rechten Lebenslinie die Beschriftung „Receiver“ hinzugefügt worden.\n</li></ul>"}, {"from": "FIG-d7c661542d94d698", "to": "FIG-32ff0abffaf22da0", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Rollenbezeichner: Die Beschriftungen „Sender“ und „Receiver“ oberhalb der beiden Lebenslinien sind entfernt worden.\n</li></ul>"}, {"from": "FIG-32ff0abffaf22da0", "to": "FIG-e2758362d57a8be5", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
